{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년 건강증진 사업에서 우선 고려하는 대상",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 청년의 신체적·정신적 건강을 보호·증진하기 위한 방안을 강구하여야 하며 예산의 범위에서 지원을 할 수 있다. 이 경우 사회·경제적 이유 등으로 건강관리에 어려움을 겪는 청년을 우선적으로 고려하여야 한다.",
          "b_ids": "청년:제18조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 청년 기본 조례상 청년 건강증진 지원 업무를 전문기관에 맡기는 방안 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "청년의 건강 보호·증진을 위한 지원 방안에는 지원 대상 선정 기준·방법·절차 등 필요한 사항 수립·시행과 함께, 지원 업무의 효율적인 추진을 위해 업무의 전부 또는 일부를 전문기관 등에 위탁하는 것이 포함된다.",
          "b_ids": "청년:제18조제2항, 청년:제18조제2항제1호, 청년:제18조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
